import assert from 'node:assert/strict';import{readFile,writeFile,mkdir}from'node:fs/promises';import{resolve}from'node:path';import{createHash}from'node:crypto';import{build}from'esbuild';import{parseCsv}from'./tools/browser-bridge/import-openbiomechanics-bats.mjs';
const evidence=resolve('../../outputs/verification-v36-obp-field-handedness-v1');await mkdir(evidence);const originalBytes=await readFile('docs/demos/measured-bat-motions.json'),data=JSON.parse(originalBytes),metaBytes=await readFile('../../outputs/参考データ/openbiomechanics/baseball_hitting/data/metadata.csv'),metadata=new Map(parseCsv(metaBytes.toString('utf8')).map(r=>[r.session_swing,r]));
const built=await build({entryPoints:['src/core/sim/contact/ReferenceBatKinematicsV1.ts'],bundle:true,format:'esm',platform:'node',write:false});const{createReferenceBatKinematicsV1}=await import('data:text/javascript;base64,'+Buffer.from(built.outputFiles[0].text).toString('base64'));
const reflectPoint=v=>({x:-v.x,y:v.y,z:v.z}),reflectAxial=v=>({x:v.x,y:-v.y,z:-v.z}),reflectedQ=q=>({w:q.w,x:q.x,y:-q.y,z:-q.z});const norm=v=>Math.hypot(v.x,v.y,v.z),near=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z)<1e-9;
const clips=[];let testedKeys=0,testedIntervals=0;
for(const clip of data.clips){
 const rawMeta=metadata.get(clip.source.motion);assert.equal(rawMeta.hitter_side,clip.side);const fixedFrames=clip.frames.map(f=>({tick:f.tick,grip:reflectPoint(f.grip),orientation:reflectedQ(f.orientation)}));const input={provenance:{clipId:clip.id,sourceSha256:clip.source.sha256},frames:clip.frames.map(f=>({tick:f.tick,grip:f.grip,orientation:f.orientation})),batLengthM:clip.normalization.batLengthM,sweetSpotT:clip.normalization.sweetSpotT,sourceTicksPerSecond:1e6,startTick:clip.frames[0].tick,ticksPerSecond:1e6,playbackRate:1,transform:{rotation:{w:1,x:0,y:0,z:0},translation:{x:0,y:0,z:0},scale:1}};
 const original=createReferenceBatKinematicsV1(input),candidate=createReferenceBatKinematicsV1({...input,frames:fixedFrames});
 const check=tick=>{const a=original.sampleContinuous(tick),b=candidate.sampleContinuous(tick);assert(near(b.state.pose.grip,reflectPoint(a.state.pose.grip)));assert(near(b.state.pose.tip,reflectPoint(a.state.pose.tip)));assert(near(b.sweetSpot,reflectPoint(a.sweetSpot)));assert(near(b.state.linearVelocity,reflectPoint(a.state.linearVelocity)));assert(near(b.state.angularVelocity,reflectAxial(a.state.angularVelocity)));assert(near(b.sweetSpotVelocity,reflectPoint(a.sweetSpotVelocity)));assert(Math.abs(norm(b.state.angularVelocity)-norm(a.state.angularVelocity))<1e-9);};
 for(let i=0;i<clip.frames.length;i++){
  const row=clip.sourceRows[i],measurement=clip.measurements[i],correctRaw={x:-Number(row.sweet_spot_y),y:Number(row.sweet_spot_z),z:Number(row.sweet_spot_x)};assert(near(reflectPoint(measurement.sweetSpot),correctRaw));check(clip.frames[i].tick);testedKeys++;
  if(i){check((clip.frames[i-1].tick+clip.frames[i].tick)/2);testedIntervals++;}
 }
 const contact=clip.contactTimeSeconds*1e6,at=original.sampleContinuous(contact),fixed=candidate.sampleContinuous(contact),expectedSign=clip.side==='R'?-1:1;
 assert((fixed.state.pose.grip.x-fixed.sweetSpot.x)*expectedSign>0);assert((at.state.pose.grip.x-at.sweetSpot.x)*expectedSign<0);
 const samples=[-.15,-.075,-.025,0,.025,.075].map(delta=>{const t=contact+delta*1e6,a=original.sampleContinuous(t),b=candidate.sampleContinuous(t);return {relativeContactSeconds:delta,original:{grip:a.state.pose.grip,tip:a.state.pose.tip,angularVelocity:a.state.angularVelocity,sweetVelocity:a.sweetSpotVelocity},candidate:{grip:b.state.pose.grip,tip:b.state.pose.tip,angularVelocity:b.state.angularVelocity,sweetVelocity:b.sweetSpotVelocity}};});
 clips.push({id:clip.id,metadataOriginal:{session_swing:rawMeta.session_swing,hitter_side:rawMeta.hitter_side},expectedBox:clip.side==='R'?'THIRD_BASE_NEGATIVE_FIELD_X':'FIRST_BASE_POSITIVE_FIELD_X',
  originalGripRelativeSweetX:at.state.pose.grip.x-at.sweetSpot.x,candidateGripRelativeSweetX:fixed.state.pose.grip.x-fixed.sweetSpot.x,
  originalAngularY:at.state.angularVelocity.y,candidateAngularY:fixed.state.angularVelocity.y,samples});
}
assert.equal(createHash('sha256').update(await readFile('docs/demos/measured-bat-motions.json')).digest('hex'),createHash('sha256').update(originalBytes).digest('hex'));
const report={status:'PASS_ORIGINAL_FIELD_MAPPING_IS_LATERALLY_REVERSED',sourceDataSha256:createHash('sha256').update(originalBytes).digest('hex'),metadataSha256:createHash('sha256').update(metaBytes).digest('hex'),
 upstreamCoordinateQuote:'(+) x points from home plate toward the pitcher’s mound, (+) y points toward the right-handed batter’s box, and (+) z points upward',
 fieldGeometry:{first:{x:27.432/Math.sqrt(2),y:0,z:27.432/Math.sqrt(2)},third:{x:-27.432/Math.sqrt(2),y:0,z:27.432/Math.sqrt(2)}},
 originalMapping:'field=(labY,labZ,labX) maps right-handed box to first-base side',candidateMapping:'field=(-labY,labZ,labX) maps right-handed box to third-base side',
 quaternionRegistration:'q=(w,x,y,z) -> (w,x,-y,-z), R_new=M R_old M, M=diag(-1,1,1)',axialVectorRegistration:'omega_new=det(M)M omega_old=(wx,-wy,-wz)',
 testedKeys,testedIntervals,sourceFilesModified:false,scope:'read-only coordinate registration experiment; not a new accepted game or a recalibrated Native source',clips};
await writeFile(resolve(evidence,'field-handedness.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({status:report.status,testedKeys,testedIntervals,clips:clips.map(c=>({id:c.id,side:c.metadataOriginal.hitter_side,originalGripRelativeSweetX:c.originalGripRelativeSweetX,candidateGripRelativeSweetX:c.candidateGripRelativeSweetX,originalAngularY:c.originalAngularY,candidateAngularY:c.candidateAngularY})),evidence},null,2));
